export function MemorialCard(a,i=!1){return`<div class="memorial-card ${i?"selected":""}" data-id="${a.id}">\n    <div class="memorial-card-image">\n      <img src="${a.image}" alt="${a.name}" loading="lazy" />\n      <div class="memorial-card-overlay" style="border-left-color: ${a.color}">\n        <span class="memorial-year">${a.built}</span>\n      </div>\n    </div>\n    <div class="memorial-card-body">\n      <h3 class="memorial-card-name">${a.name}</h3>\n      <p class="memorial-card-location">${a.city}, ${a.state}</p>\n      <p class="memorial-card-significance">${a.significance.substring(0,120)}...</p>\n      <button class="memorial-card-btn" data-id="${a.id}">\n        Explore <span class="arrow">→</span>\n      </button>\n    </div>\n  </div>`}